// The Python client: one class over urllib, one method per operation with keyword arguments,
// TypedDicts for the named schemas, and no dependency. Python 3.11 is the floor, for
// typing.NotRequired and the `X | None` spelling.

const pyClientHeader = `# Code generated by tools/sdkgen from api/openapi.yaml - DO NOT EDIT.
#
# The Python client for the Hubtask API (P-03, ADR-0057). Regenerated by ` + "`make generate`" + `; the
# specification is the source and this is the result (ADR-0004). One method per operation, over
# urllib and nothing else.
#
# SPDX-License-Identifier: Apache-2.0
from __future__ import annotations

import json
import urllib.error
import urllib.parse
import urllib.request
from typing import Any, Callable

from .types import *  # noqa: F401,F403 - the named schemas, for the annotations below


class ProblemError(Exception):
    """A refusal: the status and the problem document (RFC 9457) the server answered."""

    def __init__(self, status: int, problem: dict[str, Any]) -> None:
        self.status = status
        self.problem = problem
        code = problem.get("code", "")
        detail = problem.get("detail_code")
        super().__init__(f"hubtask: {status} {code} ({detail})" if detail else f"hubtask: {status} {code}")


class Client:
    """The client. ` + "`base_url`" + ` is the API root, ` + "`https://<host>/api/v1`" + `; ` + "`token`" + ` is the bearer
    or a callable answering the current one; ` + "`timeout`" + ` bounds every request in seconds."""

    def __init__(
        self,
        base_url: str,
        token: str | Callable[[], str | None] | None = None,
        *,
        timeout: float = 30.0,
        headers: dict[str, str] | None = None,
        opener: urllib.request.OpenerDirector | None = None,
    ) -> None:
        self.base_url = base_url.rstrip("/")
        self.token = token
        self.timeout = timeout
        self.headers = dict(headers or {})
        self.opener = opener or urllib.request.build_opener()

    def _call(
        self,
        method: str,
        template: str,
        path: dict[str, Any],
        query: dict[str, Any] | None,
        headers: dict[str, str | None],
        body: Any,
        body_kind: str,
        content_type: str | None,
        answer: str,
    ) -> Any:
        url = template
        for name, value in path.items():
            url = url.replace("{" + name + "}", urllib.parse.quote(str(value), safe=""))
        params = [(k, str(v)) for k, v in (query or {}).items() if v is not None]
        if params:
            url += "?" + urllib.parse.urlencode(params)
        sent: dict[str, str] = dict(self.headers)
        if answer == "json":
            sent["Accept"] = "application/json, application/problem+json"
        token = self.token() if callable(self.token) else self.token
        if token:
            sent["Authorization"] = f"Bearer {token}"
        for key, value in headers.items():
            if value is not None:
                sent[key] = value
        data: bytes | None = None
        if body_kind == "json":
            sent["Content-Type"] = content_type or "application/json"
            data = json.dumps(body).encode("utf-8")
        elif body_kind == "raw":
            if content_type:
                sent["Content-Type"] = content_type
            data = body if isinstance(body, (bytes, bytearray)) else str(body).encode("utf-8")
        request = urllib.request.Request(self.base_url + url, data=data, method=method, headers=sent)
        try:
            response = self.opener.open(request, timeout=self.timeout)
        except urllib.error.HTTPError as refused:
            raw = refused.read()
            problem: dict[str, Any] = {"status": refused.code, "code": ""}
            try:
                parsed = json.loads(raw) if raw else {}
                if isinstance(parsed, dict):
                    problem.update(parsed)
            except ValueError:
                pass  # not a problem document; the status is the whole answer
            problem.setdefault("status", refused.code)
            raise ProblemError(refused.code, problem) from None
        with response:
            if answer == "raw":
                return response.read()
            payload = response.read()
        if answer == "void" or response.status == 204 or not payload:
            return None
        return json.loads(payload)
`

const pyTypesHeader = `# Code generated by tools/sdkgen from api/openapi.yaml - DO NOT EDIT.
#
# The named schemas of the Hubtask API as TypedDicts (P-03). A field the contract does not
# require is NotRequired; a schema that is not an object is an alias.
#
# SPDX-License-Identifier: Apache-2.0
from __future__ import annotations

from typing import Any, Literal, NotRequired, Required, TypedDict

`

var snakeBoundary = regexp.MustCompile(`([a-z0-9])([A-Z])`)

func snake(name string) string {
	s := snakeBoundary.ReplaceAllString(name, "${1}_${2}")
	s = strings.ReplaceAll(strings.ReplaceAll(s, "-", "_"), ".", "_")
	return strings.ToLower(s)
}

// pyReserved is Python's hard keyword list (keyword.kwlist), which a class attribute cannot be
// named; `type` and `match` are soft keywords and are fine.
var pyReserved = map[string]bool{
	"False": true, "None": true, "True": true, "and": true, "as": true, "assert": true, "async": true,
	"await": true, "break": true, "class": true, "continue": true, "def": true, "del": true, "elif": true,
	"else": true, "except": true, "finally": true, "for": true, "from": true, "global": true, "if": true,
	"import": true, "in": true, "is": true, "lambda": true, "nonlocal": true, "not": true, "or": true,
	"pass": true, "raise": true, "return": true, "try": true, "while": true, "with": true, "yield": true,
}

func pyName(name string) string {
	s := snake(name)
	if pyReserved[s] {
		return s + "_"
	}
	return s
}

func pyHeaderArg(header string) string {
	switch header {
	case "X-Hubtask-Step-Up":
		return "step_up"
	}
	return pyName(header)
}

// GeneratePython writes the client and the types.
func GeneratePython(doc *Document) (client, types string) {
	var b strings.Builder
	b.WriteString(pyClientHeader)
	for _, op := range doc.Operations {
		b.WriteString("\n")
		args := []string{"self"}
		pathMap := []string{}
		for _, p := range op.PathParams {
			name := pyName(p.Name)
			args = append(args, name+": str")
			pathMap = append(pathMap, fmt.Sprintf("%q: %s", p.Name, name))
		}
		bodyKind := "none"
		if op.Body != nil {
			if isJSON(op.Body.ContentType) {
				bodyKind = "json"
				t := "dict[str, Any]"
				if op.Body.SchemaName != "" {
					t = `"` + op.Body.SchemaName + `"`
				}
				args = append(args, "body: "+t)
			} else {
				bodyKind = "raw"
				args = append(args, "body: bytes")
			}
		}
		keyword := []string{}
		if len(op.Query) > 0 {
			keyword = append(keyword, "query: dict[str, Any] | None = None")
		}
		for _, h := range op.Headers {
			keyword = append(keyword, pyHeaderArg(h.Name)+": str | None = None")
		}
		if len(keyword) > 0 {
			args = append(append(args, "*"), keyword...)
		}
		answerKind, answerType := "void", "None"
		if op.Answer != nil && op.Answer.ContentType != "" {
			if isJSON(op.Answer.ContentType) {
				answerKind = "json"
				answerType = "dict[str, Any]"
				if op.Answer.SchemaName != "" {
					answerType = `"` + op.Answer.SchemaName + `"`
				}
			} else {
				answerKind = "raw"
				answerType = "bytes"
			}
		}
		fmt.Fprintf(&b, "    def %s(%s) -> %s:\n", pyName(op.ID), strings.Join(args, ", "), answerType)
		b.WriteString("        \"\"\"" + pyDoc(op) + "\"\"\"\n")
		headers := []string{}
		for _, h := range op.Headers {
			headers = append(headers, fmt.Sprintf("%q: %s", h.Name, pyHeaderArg(h.Name)))
		}
		query := "None"
		if len(op.Query) > 0 {
			query = "query"
		}
		body := "None"
		if op.Body != nil {
			body = "body"
		}
		contentType := "None"
		if op.Body != nil {
			contentType = fmt.Sprintf("%q", op.Body.ContentType)
		}
		fmt.Fprintf(&b, "        return self._call(%q, %q, {%s}, %s, {%s}, %s, %q, %s, %q)\n",
			op.Method, op.Path, strings.Join(pathMap, ", "), query, strings.Join(headers, ", "), body, bodyKind, contentType, answerKind)
	}

	var t strings.Builder
	t.WriteString(pyTypesHeader)
	for _, schema := range doc.Schemas {
		t.WriteString("\n")
		if schema.Properties == nil {
			fmt.Fprintf(&t, "%s = %s\n", schema.Name, schema.Alias)
			continue
		}
		if needsFunctional(schema) {
			// A key Python cannot spell as an attribute (`from`, `in`): the functional syntax
			// takes any string as a key.
			fmt.Fprintf(&t, "%s = TypedDict(%q, {\n", schema.Name, schema.Name)
			for _, p := range schema.Properties {
				annotation := p.Type
				if p.Required {
					annotation = "Required[" + annotation + "]"
				}
				fmt.Fprintf(&t, "    %q: %s,\n", p.Name, annotation)
			}
			t.WriteString("}, total=False)\n")
			continue
		}
		fmt.Fprintf(&t, "class %s(TypedDict, total=False):\n", schema.Name)
		if schema.Description != "" {
			t.WriteString("    \"\"\"" + pyDocLine(schema.Description) + "\"\"\"\n")
		}
		if len(schema.Properties) == 0 {
			t.WriteString("    pass\n")
		}
		for _, p := range schema.Properties {
			annotation := p.Type
			if p.Required {
				annotation = "Required[" + annotation + "]"
			}
			fmt.Fprintf(&t, "    %s: %s\n", p.Name, annotation)
		}
	}
	return b.String(), t.String()
}

// needsFunctional says whether a schema has a key the class syntax cannot spell.
func needsFunctional(schema Schema) bool {
	for _, p := range schema.Properties {
		if pyReserved[p.Name] || strings.ContainsAny(p.Name, "-. ") {
			return true
		}
	}
	return false
}

func pyDoc(op Operation) string {
	line := op.Summary
	if line == "" {
		line = op.Method + " " + op.Path
	}
	if op.Deprecated {
		line += " (deprecated)"
	}
	return pyDocLine(line)
}

func pyDocLine(s string) string {
	s = strings.ReplaceAll(s, `"""`, `'''`)
	s = strings.ReplaceAll(s, "\\", "\\\\")
	if i := strings.Index(s, "\n"); i >= 0 {
		s = s[:i]
	}
	return strings.TrimSpace(s)
}
